import React from "react";
import { FaTrophy, FaProjectDiagram, FaCalendarAlt, FaPalette, FaBolt, FaUserGraduate, FaLeaf } from "react-icons/fa";

const Projects = () => {
  return (
    <section className="projects-page">

      <h2 className="title">My Project Journey</h2>

      <div className="timeline">

        {/* ENERGY PULSE */}
        <div className="node left">
          <div className="dot"></div>
          <div className="content">
            <div className="icon"><FaBolt /></div>
            <h3>EnergyPulse</h3>
            <p>
              Developed the frontend of an AI-driven smart home dashboard with real-time biometric and energy monitoring.
            </p>
            <span>Tech: React.js</span>
          </div>
        </div>

        {/* STUDENT PORTAL */}
        <div className="node right">
          <div className="dot"></div>
          <div className="content">
            <div className="icon"><FaUserGraduate /></div>
            <h3>Student Portal Management</h3>
            <p>
              Built a full-stack system using Java & Spring Boot for managing student records and authentication.
            </p>
            <span>Spring Boot, MySQL, JS</span>
          </div>
        </div>

        {/* FARM2FORK */}
        <div className="node left">
          <div className="dot"></div>
          <div className="content">
            <div className="icon"><FaLeaf /></div>
            <h3>Farm2Fork</h3>
            <p>
              Created a responsive frontend connecting farmers and consumers through a smooth shopping interface.
            </p>
            <span>HTML, CSS, JavaScript</span>
          </div>
        </div>

        {/* COGNI FLOW */}
        <div className="node right highlight">
          <div className="dot"></div>
          <div className="content">
            <div className="icon">🧠</div>
            <h3>Cogni Flow</h3>
            <p>
              Designed a cognitive-flow based UI system focused on structured interaction and smooth user experience.
            </p>
            <span>HTML, CSS, JavaScript</span>
          </div>
        </div>

      </div>

      <style>{`

        .projects-page {
          min-height: 100vh;
          padding: 60px 10%;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
          font-family: "Poppins", sans-serif;
        }

        .title {
          text-align: center;
          font-size: 38px;
          color: #38BDF8;
          margin-bottom: 60px;
        }

        /* TIMELINE LINE */
        .timeline {
          position: relative;
          width: 100%;
        }

        .timeline::before {
          content: "";
          position: absolute;
          left: 50%;
          top: 0;
          height: 100%;
          width: 2px;
          background: rgba(56,189,248,0.25);
          transform: translateX(-50%);
        }

        /* NODE */
        .node {
          position: relative;
          width: 50%;
          padding: 20px 40px;
        }

        .node.left {
          left: 0;
          text-align: right;
        }

        .node.right {
          left: 50%;
        }

        /* DOT */
        .dot {
          position: absolute;
          top: 30px;
          width: 12px;
          height: 12px;
          background: #38BDF8;
          border-radius: 50%;
          box-shadow: 0 0 12px #38BDF8;
        }

        .node.left .dot {
          right: -6px;
        }

        .node.right .dot {
          left: -6px;
        }

        /* CONTENT BOX */
        .content {
          display: inline-block;
          background: rgba(255,255,255,0.05);
          padding: 20px;
          border-radius: 14px;
          border: 1px solid rgba(56,189,248,0.2);
          transition: 0.3s;
        }

        .content:hover {
          transform: scale(1.02);
          box-shadow: 0 0 25px rgba(56,189,248,0.25);
        }

        .icon {
          font-size: 24px;
          color: #38BDF8;
          margin-bottom: 8px;
        }

        h3 {
          margin: 5px 0;
          color: #e2e8f0;
        }

        p {
          color: #cbd5e1;
          font-size: 14px;
          line-height: 1.6;
        }

        span {
          display: inline-block;
          margin-top: 8px;
          color: #38BDF8;
          font-weight: 600;
          font-size: 13px;
        }

        /* HIGHLIGHT PROJECT */
        .highlight .content {
          border: 1px solid #38BDF8;
          box-shadow: 0 0 30px rgba(56,189,248,0.2);
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .timeline::before {
            left: 8px;
          }

          .node {
            width: 100%;
            padding-left: 30px;
            padding-right: 10px;
            text-align: left;
          }

          .node.left,
          .node.right {
            left: 0;
          }

          .dot {
            left: 0 !important;
          }
        }

      `}</style>

    </section>
  );
};

export default Projects;
